fn is_close_i8(a: i8, b: i8, tol: i8) -> bool {
    // Requires that the tolerance is non-negative
    // Ensures that the result is true if the absolute difference is less than the tolerance
    // Ensures that the result is false otherwise
    // This function has no side effects and is pure
    // #[verus::spec]
    // requires tol >= 0;
    // ensures (result == (a - b).abs() < tol);
    // ensures (result == true) <=> ((a - b).abs() < tol);
    // ensures (result == false) <=> !((a - b).abs() < tol);
    let diff = (a - b).abs();
    diff < tol
}

fn np_isclose(a: Vec<i8>, b: Vec<i8>, tol: i8) -> Vec<bool> {
    // Requires that the lengths of the input vectors are equal
    // Requires that the tolerance is non-negative
    // Ensures that the result vector has the same length as the input vectors
    // Ensures that each element in the result vector corresponds to the closeness of the elements in the input vectors
    // #[verus::spec]
    // requires a.len() == b.len();
    // requires tol >= 0;
    // ensures result.len() == a.len();
    // ensures forall|i: usize| 0 <= i < a.len() ==> (result[i] == is_close_i8(a[i], b[i], tol));
    // decreases a.len();
    let mut result = Vec::with_capacity(a.len());
    
    // Iterate over the elements of both vectors
    for (&x, &y) in a.iter().zip(b.iter()) {
        // Use the is_close_i8 function to determine closeness
        result.push(is_close_i8(x, y, tol));
    }
    
    result
}

